export type ItemCurrency = 'units' | 'nanites' | 'quicksilver'

export interface ItemInfo {
  /** Base galactic-trade value per unit (before economy modifiers). */
  value: number
  currency: ItemCurrency
  /** Item family, e.g. 'Trade Goods (Scientific)' or 'Salvaged Scrap'. */
  group: string
  /** Sole purpose is being sold — always safe to cash in. */
  isTradeGood: boolean
  /** Consumed by crafting, refining, cooking or tech recharging. */
  isIngredient: boolean
}

const CURRENCIES: ItemCurrency[] = ['units', 'nanites', 'quicksilver']

/** Expand a packed tuple (static table or live AssistantNMS data). */
export function infoFromTuple(tuple: ItemInfoTuple): ItemInfo {
  const [value, currency, group, flags] = tuple
  return {
    value,
    currency: CURRENCIES[currency] ?? 'units',
    group,
    isTradeGood: (flags & 1) !== 0,
    isIngredient: (flags & 2) !== 0
  }
}

/** Value/usage info for a save-file item id ('^' stripped), or null. */
export function itemInfo(itemId: string): ItemInfo | null {
  const tuple = ITEM_INFO[itemId.split('#')[0]]
  return tuple ? infoFromTuple(tuple) : null
}

/** Static tuple for an item id, for merging with live data. */
export function itemInfoTuple(itemId: string): ItemInfoTuple | null {
  return ITEM_INFO[itemId.split('#')[0]] ?? null
}
